// out: Try-parse pattern — return value says success, out carries the result
public static bool TryParsePort(string text, out int port)
{
    port = 0;
    return int.TryParse(text, NumberStyles.None, CultureInfo.InvariantCulture, out port)
           && port is >= 1 and <= 65535;
}

// ref: in-and-out — the method mutates the caller's variable
public static void Increment(ref int counter)
{
    counter++;   // caller sees the change; no copy of the variable
}

// in: read-only reference to a large struct — no copy into the method
public static decimal Total(in Rect area, in Rect other)
{
    // area.Width = 10;  // ❌ compile error — in parameters are read-only
    return area.Width * area.Height + other.Width * other.Height;
}

// Calling convention mirrors the declaration:
var ok = TryParsePort("8080", out var port);  // out var — no pre-declaration needed
Increment(ref port);                          // ref needs an existing variable
var total = in Total(in bigRect, in otherRect); // 'in' at call site is optional

// ref locals and ref returns — alias without copying
static ref int Max(ref int a, ref int b) => ref (a > b ? ref a : ref b);
ref var winner = ref Max(ref xs[0], ref xs[1]);
winner = 99;   // writes into xs — the alias IS the storage

